5: <fieldset><legend>検索条件</legend><div class="fields"><label>学籍番号<input asp-for="Criteria.StudentNo" id="SRC-001" maxlength="30"></label><label>氏名<input asp-for="Criteria.Name" id="SRC-002" maxlength="16"></label><label>氏名カナ<input asp-for="Criteria.Kana" id="SRC-003" maxlength="72"></label><label>年度<select asp-for="Criteria.SchoolYear" id="SRC-004" disabled="@Model.Criteria.UnassignedOnly"><option value="">すべて</option>@foreach(var y in Model.Lookups.Classes.Select(c=>c.SchoolYear).Distinct().OrderDescending()){<option value="@y">@y</option>}</select></label><label>学年<select asp-for="Criteria.GradeCode" id="SRC-005" disabled="@Model.Criteria.UnassignedOnly"><option value="">すべて</option>@foreach(var c in codes.Where(c=>c.CategoryId=="GRADE")){<option value="@c.CodeValue">@c.CodeName</option>}</select></label><label>クラス<select asp-for="Criteria.ClassId" id="SRC-006" disabled="@Model.Criteria.UnassignedOnly"><option value="">すべて</option>@foreach(var c in Model.Lookups.Classes.Where(c=>(Model.Criteria.SchoolYear is null||c.SchoolYear==Model.Criteria.SchoolYear)&&(string.IsNullOrEmpty(Model.Criteria.GradeCode)||c.GradeCode==Model.Criteria.GradeCode))){<option value="@c.ClassId">@c.SchoolYear @c.ClassCode @c.ClassName @(!c.IsActive?"（停止）":"")</option>}</select></label><label class="check"><input asp-for="Criteria.UnassignedOnly" id="SRC-007">未所属のみ</label><fieldset><legend>在籍区分</legend>@foreach(var c in codes.Where(c=>c.CategoryId=="ENROLLMENT_STATUS")){<label class="check"><input type="checkbox" name="Criteria.StatusCodes" value="@c.CodeValue" checked="@Model.Criteria.StatusCodes.Contains(c.CodeValue)">@c.CodeName</label>}<small>全解除はすべて</small></fieldset><label>都道府県<select asp-for="Criteria.PrefectureCode" id="SRC-009"><option value="">すべて</option>@foreach(var c in codes.Where(c=>c.CategoryId=="PREFECTURE")){<option value="@c.CodeValue">@c.CodeName</option>}</select></label><label>電話番号<input asp-for="Criteria.PhoneNumber" id="SRC-010" maxlength="40"></label><label>入学日・開始<input asp-for="Criteria.AdmissionFrom" id="SRC-011" type="date"></label><label>入学日・終了<input asp-for="Criteria.AdmissionTo" id="SRC-012" type="date"></label></div><div class="actions"><button type="submit" class="primary">検索</button><button type="submit" formaction="/students/options">候補を更新</button></div></fieldset></form>
