13:     [HttpPost("search")] public async Task<IActionResult> Search([Bind(Prefix="Criteria")]StudentSearchInput input,string contextId,string contextRevision,string tabId,int pageSize=20,string sortKey="studentNo",string sortDirection="asc",CancellationToken ct=default) {
14:         await FormGuard("Criteria",typeof(StudentSearchInput),"ContextId","ContextRevision","TabId","PageSize","SortKey","SortDirection");if(!Request.Form.ContainsKey("Criteria.StatusCodes"))input.StatusCodes=[];var entry=contexts.Get(contextId,identity.CurrentUser,tabId);object data=WebStudentCoordinator.Present(entry,null);
15:         if(ModelState.IsValid) { try {data=await coordinator.Search(new SearchRequest {ContextId=contextId,ContextRevision=contextRevision,Criteria=input,PageSize=pageSize,SortKey=sortKey,SortDirection=sortDirection},tabId,ct);}catch(WebFault e) {ModelState.AddModelError(e.Field??"",e.Message);Response.StatusCode=e.Status;} } else Response.StatusCode=422;
16:         var model=await SearchModel(entry,data,input,"",ct);model.PageSize=pageSize;model.SortKey=sortKey;model.SortDirection=sortDirection;return View("Search",model);
17:     }
