20:     }
21:     [HttpPost("clear")] public async Task<IActionResult> Clear(ContextRequest input,string tabId,CancellationToken ct) {await FormGuard(null,typeof(ContextRequest),"TabId");var data=await coordinator.Clear(input,tabId,ct);ModelState.Clear();var entry=contexts.Get(input.ContextId,identity.CurrentUser,tabId);return View("Search",await SearchModel(entry,data,new(),"",ct));}
22:     [HttpPost("options")] public async Task<IActionResult> Options([Bind(Prefix="Criteria")]StudentSearchInput input,string contextId,string contextRevision,string tabId,int pageSize=20,string sortKey="studentNo",string sortDirection="asc",CancellationToken ct=default) {await FormGuard("Criteria",typeof(StudentSearchInput),"ContextId","ContextRevision","TabId","PageSize","SortKey","SortDirection");if(!Request.Form.ContainsKey("Criteria.StatusCodes"))input.StatusCodes=[];var entry=contexts.Get(contextId,identity.CurrentUser,tabId);if(input.UnassignedOnly){input.SchoolYear=null;input.GradeCode=null;input.ClassId=null;ModelState.Remove("Criteria.SchoolYear");ModelState.Remove("Criteria.GradeCode");ModelState.Remove("Criteria.ClassId");}var model=await SearchModel(entry,WebStudentCoordinator.Present(entry,entry.LastResult),input,"条件を変更しました。検索を押すと一覧に反映します。",ct);if(!string.IsNullOrEmpty(input.ClassId)&&!model.Lookups.Classes.Any(c=>c.ClassId.ToString()==input.ClassId&&(input.SchoolYear is null||c.SchoolYear==input.SchoolYear)&&(string.IsNullOrEmpty(input.GradeCode)||c.GradeCode==input.GradeCode))){input.ClassId=null;ModelState.Remove("Criteria.ClassId");model.Message="上位条件に合わないクラスを解除しました。";}return View("Search",model);}
23:     [HttpGet("new")] public Task<IActionResult> New(string? returnContextId,CancellationToken ct)=>Load(null,returnContextId,ct);
24:     [HttpGet("{id:long}")] public Task<IActionResult> Edit(long id,string? returnContextId,CancellationToken ct)=>Load(id,returnContextId,ct);
25:     private async Task<IActionResult> Load(long? id,string? context,CancellationToken ct) {var data=await coordinator.Edit(id,context,ct);var returnRevision=string.IsNullOrEmpty(context)?null:contexts.Get(context,identity.CurrentUser).Revision.ToString(System.Globalization.CultureInfo.InvariantCulture);return View("Edit",new StudentEditPageModel {StudentId=id,Input=data.Form,Detail=data.Detail,Lookups=data.Lookups,User=identity.CurrentUser,ReturnRevision=returnRevision,SnapshotId=snapshots.Create(identity.CurrentUser,id,data.Detail,data.Form,returnRevision)});}
26:     [HttpPost("create")] public Task<IActionResult> Create([Bind(Prefix="Input")]StudentSaveInput input,string snapshotId,CancellationToken ct)=>Save(null,input,snapshotId,ct);
27:     [HttpPost("{id:long}/update")] public Task<IActionResult> Update(long id,[Bind(Prefix="Input")]StudentSaveInput input,string snapshotId,CancellationToken ct)=>Save(id,input,snapshotId,ct);
28:     private async Task<IActionResult> Save(long? id,StudentSaveInput input,string snapshotId,CancellationToken ct) {
29:         await FormGuard("Input",typeof(StudentSaveInput),"SnapshotId");identity.CreateOrUpdate();var snapshot=snapshots.Get(snapshotId,identity.CurrentUser,id);coordinator.CheckReturn(input.ReturnContextId);if(input.ReturnContextId!=snapshot.Original.ReturnContextId)throw new WebFault(403,"編集時と異なる復帰先は使用できません。");SaveResult? result=null;
30:         if(ModelState.IsValid) {try {result=await coordinator.Save(id,input,ct);foreach(var e in result.Errors)ModelState.AddModelError(e.Field,e.Message);}catch(WebFault e){ModelState.AddModelError(e.Field??"",e.Message);Response.StatusCode=e.Status;} } else Response.StatusCode=422;
31:         if(result?.Outcome==Outcome.Saved)return ReturnAfterSave(input.ReturnContextId,snapshot.ReturnRevision,"保存しました。");
32:         if(result is not null){Response.StatusCode=WebPresentation.Status(result.Outcome);input.DuplicateToken=result.ConfirmationToken;ModelState.Remove("Input.DuplicateToken");}
33:         return View("Edit",new StudentEditPageModel {StudentId=id,Input=input,Detail=snapshot.Detail,SnapshotId=snapshotId,ReturnRevision=snapshot.ReturnRevision,Result=result,Lookups=await service.LookupAsync(ct),User=identity.CurrentUser,Message=result?.Outcome==Outcome.NoChange?"変更はありません。":""});
34:     }
35:     [HttpPost("reset")] public async Task<IActionResult> Reset(string snapshotId,string? studentId,CancellationToken ct) {await FormGuard(null,typeof(EmptyInput),"SnapshotId","StudentId");identity.Read();var id=IdParser.Optional(studentId,"REG-INT-012");var snapshot=snapshots.Get(snapshotId,identity.CurrentUser,id);ModelState.Clear();return View("Edit",new StudentEditPageModel {StudentId=id,Input=EditorSnapshotStore.Copy(snapshot.Original),Detail=snapshot.Detail,SnapshotId=snapshotId,ReturnRevision=snapshot.ReturnRevision,Lookups=await service.LookupAsync(ct),User=identity.CurrentUser,Message="入力を読込時の値へ戻しました。"});}
36:     private sealed class EmptyInput { }
37:     [HttpPost("{id:long}/delete")] public async Task<IActionResult> Delete(long id,StudentDeleteInput input,string snapshotId,CancellationToken ct) {await FormGuard(null,typeof(StudentDeleteInput),"SnapshotId");identity.Read();var snapshot=snapshots.Get(snapshotId,identity.CurrentUser,id);if(input.ReturnContextId!=snapshot.Original.ReturnContextId)throw new WebFault(403,"編集時と異なる復帰先は使用できません。");var result=await coordinator.Delete(id,input,ct);if(result.Outcome==Outcome.Saved)return ReturnAfterSave(input.ReturnContextId,snapshot.ReturnRevision,"論理削除しました。");foreach(var e in result.Errors)ModelState.AddModelError(e.Field,e.Message);Response.StatusCode=WebPresentation.Status(result.Outcome);return await Load(id,input.ReturnContextId,ct);}
38:     private IActionResult ReturnAfterSave(string? context,string? revision,string message) {if(string.IsNullOrEmpty(context)){var entry=coordinator.NewContext();context=entry.Id;revision=entry.Revision.ToString(System.Globalization.CultureInfo.InvariantCulture);}flash.Put(identity.CurrentUser,context,message);Response.StatusCode=303;Response.Headers.Location="/students?contextId="+Uri.EscapeDataString(context)+"&contextRevision="+Uri.EscapeDataString(revision??"");return new EmptyResult();}
39:     private async Task<StudentSearchPageModel> SearchModel(SearchContextStore.Entry entry,object data,StudentSearchInput input,string message,CancellationToken ct)=>new() {Criteria=input,Lookups=await service.LookupAsync(false,ct),Context=entry,User=identity.CurrentUser,Data=StudentSearchPageModel.Json(data),Message=message,PageSize=entry.Applied?.PageSize??20,SortKey=entry.Applied?.SortKey??"studentNo",SortDirection=entry.Applied?.SortDirection??"asc"};
40:     private static StudentSearchInput From(SearchCriteria c)=>new() {StudentNo=c.StudentNo??"",Name=c.StudentName??"",Kana=c.StudentNameKana??"",SchoolYear=c.SchoolYear,GradeCode=c.GradeCode,ClassId=c.ClassId?.ToString(System.Globalization.CultureInfo.InvariantCulture),UnassignedOnly=c.UnassignedOnly,StatusCodes=c.EnrollmentStatusCodes,PrefectureCode=c.PrefectureCode,PhoneNumber=c.PhoneNumber??"",AdmissionFrom=c.AdmissionFrom,AdmissionTo=c.AdmissionTo};
41:     private async Task FormGuard(string? prefix,Type inputType,params string[] extras) {var allowed=new HashSet<string>(extras,StringComparer.OrdinalIgnoreCase){"__RequestVerificationToken","__Invariant"};foreach(var property in inputType.GetProperties()){var key=(prefix is null?"":prefix+".")+property.Name;if(property.PropertyType==typeof(BirthDateInput)){foreach(var component in new[]{"Era","Year","Month","Day"})allowed.Add(key+"."+component);}else allowed.Add(key);}var form=await Request.ReadFormAsync();foreach(var key in form.Keys){if(!allowed.Contains(key))throw new WebFault(400,"許可されていない項目が送信されました。");if(key=="__Invariant"&&form[key].Any(value=>value is null||!allowed.Contains(value)))throw new WebFault(400,"不正なフォーム書式メタ情報です。");if(form[key].Count>1&&key!="__Invariant"&&!key.EndsWith("StatusCodes",StringComparison.OrdinalIgnoreCase)&&!key.EndsWith("UnassignedOnly",StringComparison.OrdinalIgnoreCase))throw new WebFault(400,"同名項目が重複しています。");}}
42: }
source/Infrastructure/WebStudentCoordinator.cs
1: using StudentManagement.Core;
2: namespace StudentManagement.Web;
3: public sealed class WebStudentCoordinator(IStudentService service,RequestIdentity identity,SearchContextStore contexts)
4: {
5:     public SearchContextStore.Entry NewContext(string? tab=null)=>contexts.Create(identity.CurrentUser,tab);
6:     public void CheckReturn(string? id) { if(!string.IsNullOrEmpty(id)) contexts.Get(id,identity.CurrentUser); }
7:     public async Task<object> Search(SearchRequest request,string? tab,CancellationToken ct) {
8:         identity.Read(); var criteria=request.Criteria.ToCriteria(request.PageSize,request.SortKey,request.SortDirection);
9:         return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result; entry.Revision++; return Present(entry,result); },ct);
10:     }
11:     public async Task<object> Page(PageRequest request,string? tab,CancellationToken ct) {
12:         identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) throw new WebFault(409,"先に検索してください。"); var criteria=SearchContextStore.Copy(entry.Applied); criteria.Page=criteria.PageSize!=request.PageSize||criteria.SortKey!=request.SortKey||criteria.SortDirection!=request.SortDirection?1:request.Page; criteria.PageSize=request.PageSize; criteria.SortKey=request.SortKey;criteria.SortDirection=request.SortDirection; var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); if(!result.LimitExceeded&&criteria.Page>Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize)) { criteria.Page=Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize);result=await service.SearchAsync(criteria,ct);EnsureSearch(result); } entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct);
13:     }
14:     public async Task<object> Resume(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) return Present(entry,null); var result=await service.SearchAsync(entry.Applied,ct);EnsureSearch(result);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct); }
15:     public Task<object> Clear(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return contexts.Use(request,identity.CurrentUser,tab,entry=> { entry.Applied=null;entry.LastResult=null;entry.Revision++;return Task.FromResult(Present(entry,null)); },ct); }
16:     public async Task<object> Options(OptionsRequest request,CancellationToken ct) { identity.Read(); if(request.Usage=="register") identity.CreateOrUpdate(); StudentDetail? existing=null; if(!string.IsNullOrEmpty(request.StudentId)) existing=await service.GetAsync(IdParser.Required(request.StudentId,"REG-INT-012"),ct) ?? throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103"); return WebPresentation.Lookups(await service.LookupAsync(request.Usage=="register",ct),request.Usage,existing,request.SchoolYear,request.GradeCode,request.EnrollmentStatusCode,request.AdmissionDate,request.EnrollmentEndDate); }
17:     public async Task<(StudentDetail? Detail,StudentSaveInput Form,LookupSet Lookups)> Edit(long? id,string? contextId,CancellationToken ct) { identity.Read();CheckReturn(contextId); if(id is null) identity.CreateOrUpdate(); var detail=id is null?null:await service.GetAsync(id.Value,ct)??throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103");var lookup=await service.LookupAsync(ct);return(detail,StudentSaveInput.From(detail,contextId,lookup),lookup); }
