121:             DateOnly? to = string.IsNullOrEmpty(criteria.AdmissionTo) ? null : JapaneseDateService.ParseIso(criteria.AdmissionTo,day);
122:             if (from > to) throw new ArgumentException("E-STU-006: 開始日は終了日以前にしてください。");
123:             await using var connection = await Open(ct);
124:             await using var tx = (SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.Snapshot,ct);
125:             if (grade is not null && !await CodeExists(connection,tx,"GRADE",grade,ct) || prefecture is not null && !await CodeExists(connection,tx,"PREFECTURE",prefecture,ct)) throw new ArgumentException("E-STU-009: 指定コードが存在しません。");
126:             if (criteria.SchoolYear is not null) {
127:                 await using var yearCheck = Command(connection,tx,"SELECT COUNT_BIG(*) FROM dbo.m_class WHERE school_year=@year");
128:                 Param(yearCheck,"@year",SqlDbType.SmallInt,criteria.SchoolYear);
129:                 if ((long)(await yearCheck.ExecuteScalarAsync(ct))! == 0) throw new ArgumentException("E-STU-014: 年度候補が存在しません。");
130:             }
131:             if (criteria.ClassId is { } classId) {
132:                 await using var classCheck = Command(connection,tx,"SELECT school_year,grade_code FROM dbo.m_class WHERE class_id=@id");
133:                 Param(classCheck,"@id",SqlDbType.BigInt,classId);
134:                 await using var reader = await classCheck.ExecuteReaderAsync(ct);
135:                 if (!await reader.ReadAsync(ct) || criteria.SchoolYear is not null && Convert.ToInt32(reader[0]) != criteria.SchoolYear || grade is not null && reader.GetString(1) != grade) throw new ArgumentException("E-STU-014: 年度・学年・クラスが一致しません。");
136:             }
137:             var predicates = new List<string>{ "s.is_deleted=0" };
138:             var parameters = new List<(string Name, SqlDbType Type, object? Value, int Size)>();
139:             void Where(string sql, string key, SqlDbType type, object? value, int size = 0) { if (value is not null) { predicates.Add(sql); parameters.Add((key,type,value,size)); } }
140:             Where("s.student_no LIKE @no ESCAPE '!'","@no",SqlDbType.VarChar,no is null ? null : StudentNormalizer.EscapeLike(no)+"%",31);
141:             Where("s.name_key LIKE @name ESCAPE '!'","@name",SqlDbType.NVarChar,name is null ? null : "%"+StudentNormalizer.EscapeLike(name)+"%",642);
142:             Where("s.kana_key LIKE @kana ESCAPE '!'","@kana",SqlDbType.NVarChar,kana is null ? null : "%"+StudentNormalizer.EscapeLike(kana)+"%",74);
143:             Where("c.school_year=@year","@year",SqlDbType.SmallInt,criteria.SchoolYear);
144:             Where("c.grade_code=@grade","@grade",SqlDbType.VarChar,grade,2);
145:             Where("s.class_id=@class","@class",SqlDbType.BigInt,criteria.ClassId);
146:             if(criteria.UnassignedOnly) predicates.Add("s.class_id IS NULL");
