196:     public Task<LookupSet> LookupAsync(CancellationToken ct = default) => LookupAsync(true,ct);
197:     public async Task<LookupSet> LookupAsync(bool includeOccupancy,CancellationToken ct = default)
198:     {
199:         _ = User(); await using var connection = await Open(ct);
200:         await using var tx=(SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.Snapshot,ct);
201:         var occupied=includeOccupancy ? "(SELECT COUNT(*) FROM dbo.m_student s WHERE s.class_id=c.class_id AND s.is_deleted=0 AND s.enrollment_status_code IN ('01','02'))" : "CONVERT(int,0)";
202:         await using var command=Command(connection,tx,$"""
203:             SELECT c.category_id,c.code_value,c.code_name,c.display_order,
204:                    CONVERT(bit,CASE WHEN c.is_active=1 AND k.is_active=1 THEN 1 ELSE 0 END) is_active,c.valid_from,c.valid_to,c.is_protected
205:               FROM dbo.m_code c JOIN dbo.m_code_category k ON k.category_id=c.category_id ORDER BY c.category_id,c.display_order,c.code_value;
206:             SELECT c.*, {occupied} occupied
207:               FROM dbo.m_class c LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code
208:              ORDER BY c.school_year DESC,g.display_order,c.display_order,c.class_code,c.class_id;
209:             """);
210:         var codes=new List<CodeEntry>(); var classes=new List<SchoolClass>();
211:         await using(var reader=await command.ExecuteReaderAsync(ct)) {
212:             while(await reader.ReadAsync(ct)) codes.Add(new(String(reader,"category_id")!,String(reader,"code_value")!,String(reader,"code_name")!,Convert.ToInt32(reader["display_order"]),reader.GetBoolean(reader.GetOrdinal("is_active")),Date(reader,"valid_from"),reader.IsDBNull(reader.GetOrdinal("valid_to"))?null:Date(reader,"valid_to"),reader.GetBoolean(reader.GetOrdinal("is_protected"))));
213:             await reader.NextResultAsync(ct);
214:             while(await reader.ReadAsync(ct)) classes.Add(new(Long(reader,"class_id"),Convert.ToInt32(reader["school_year"]),String(reader,"grade_code")!,String(reader,"class_code")!,String(reader,"class_name")!,Date(reader,"valid_from"),Date(reader,"valid_to"),reader.IsDBNull(reader.GetOrdinal("capacity"))?null:Convert.ToInt32(reader["capacity"]),Convert.ToInt32(reader["occupied"]),reader.GetBoolean(reader.GetOrdinal("is_active"))));
215:         }
216:         await tx.CommitAsync(ct); return new(codes,classes);
217:     }
218:     private static async Task<bool> CodeExists(SqlConnection connection,SqlTransaction tx,string category,string value,CancellationToken ct)
219:     {
220:         await using var command=Command(connection,tx,"SELECT COUNT_BIG(*) FROM dbo.m_code WHERE category_id=@category AND code_value=@value");
221:         Param(command,"@category",SqlDbType.VarChar,category,24); Param(command,"@value",SqlDbType.VarChar,value,10);
222:         return (long)(await command.ExecuteScalarAsync(ct))! == 1;

