8:         get { var p=Context.User; if(p.Identity?.IsAuthenticated!=true) throw new WebFault(401,"認証が失効しました。再認証してください。");
9:             var id=p.FindFirstValue(ClaimTypes.NameIdentifier); var session=p.FindFirstValue("login_session"); var role=p.FindFirstValue(ClaimTypes.Role);
10:             if(string.IsNullOrWhiteSpace(id)||id.EnumerateRunes().Count()>64||string.IsNullOrWhiteSpace(session)||session.Length>64||!Enum.TryParse<Role>(role,out var r)) throw new WebFault(401,"認証情報を確認できません。"); return new(id,session,r); }
11:     }
12:     public string TabId => Context.Request.Headers["X-Tab-Id"].FirstOrDefault() ?? Context.Request.Query["tabId"].FirstOrDefault() ?? "";
13:     public void Read() { _=CurrentUser; }
14:     public void CreateOrUpdate() { if(CurrentUser.Role==Role.Viewer) throw new WebFault(403,"この操作を実行する権限がありません。"); }
15:     public void Administrator() { if(CurrentUser.Role!=Role.Administrator) throw new WebFault(403,"管理者権限が必要です。"); }
16:     public object Permissions => new { read=true,create=CurrentUser.Role!=Role.Viewer,update=CurrentUser.Role!=Role.Viewer,@delete=CurrentUser.Role==Role.Administrator,maintain=CurrentUser.Role==Role.Administrator };
17: }
